<script>
document.addEventListener('DOMContentLoaded',()=>{
const definitions=<?=json_encode($attributeDefinitions,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_THROW_ON_ERROR)?>;
let editorCounter=0;
const addRow=(editor,key='',value='')=>{const row=document.createElement('div');row.className='row g-2 align-items-center';row.dataset.attributeRow='';const keyCell=document.createElement('div');keyCell.className='col-md-5';const keyInput=document.createElement('input');keyInput.className='form-control form-control-sm';keyInput.name='attribute_keys[]';keyInput.setAttribute('list',editor.dataset.listId);keyInput.placeholder='Klíč parametru';keyInput.value=key;keyCell.append(keyInput);const valueCell=document.createElement('div');valueCell.className='col-md-6';valueCell.dataset.valueCell='';const actionCell=document.createElement('div');actionCell.className='col-md-1 d-grid';const remove=document.createElement('button');remove.type='button';remove.className='btn btn-sm btn-outline-danger';remove.dataset.removeAttribute='';remove.setAttribute('aria-label','Odebrat parametr');remove.textContent='×';actionCell.append(remove);row.append(keyCell,valueCell,actionCell);editor.querySelector('[data-attribute-rows]').append(row);
const adapt=()=>{const definition=definitions[keyInput.value]||null;const current=valueCell.querySelector('[data-attribute-value]');const currentValue=current?current.value:value;if(definition&&Number(definition.active)===1&&definition.value_type==='choice'){const select=document.createElement('select');select.className='form-select form-select-sm';select.name='attribute_values[]';select.dataset.attributeValue='';const blank=document.createElement('option');blank.value='';blank.textContent='Vyberte';select.append(blank);const choices=definition.choices||[];if(currentValue!==''&&!choices.includes(currentValue)){const legacy=document.createElement('option');legacy.value=currentValue;legacy.textContent=currentValue+' (stávající hodnota)';legacy.selected=true;select.append(legacy);}for(const choice of choices){const option=document.createElement('option');option.value=choice;option.textContent=choice;option.selected=choice===currentValue;select.append(option);}valueCell.replaceChildren(select);}else{const input=document.createElement('input');input.className='form-control form-control-sm';input.name='attribute_values[]';input.dataset.attributeValue='';input.placeholder=definition&&definition.value_type==='number'?'Číselná hodnota':'Hodnota';input.value=currentValue;valueCell.replaceChildren(input);}};
keyInput.addEventListener('change',adapt);remove.addEventListener('click',()=>row.remove());adapt();};
for(const textarea of document.querySelectorAll('textarea[name="attributes_json"]')){let values={};try{values=JSON.parse(textarea.value);if(!values||Array.isArray(values)||typeof values!=='object')values={};}catch{values={};}const host=textarea.parentElement;host.innerHTML='<label class="form-label">Parametry varianty</label><datalist></datalist><div class="vstack gap-2" data-attribute-rows></div><button class="btn btn-sm btn-outline-secondary mt-2" type="button" data-add-attribute>Přidat parametr</button><div class="form-text">Klíč můžete vybrat z číselníku nebo napsat vlastní.</div>';host.dataset.attributeEditor='';host.dataset.listId='attribute-runtime-'+(++editorCounter);host.querySelector('datalist').id=host.dataset.listId;for(const definition of Object.values(definitions)){if(Number(definition.active)!==1)continue;const option=document.createElement('option');option.value=definition.attribute_key;option.textContent=definition.display_name;host.querySelector('datalist').append(option);}for(const[key,value]of Object.entries(values))addRow(host,key,typeof value==='object'?JSON.stringify(value):String(value));if(Object.keys(values).length===0)addRow(host);}
for(const editor of document.querySelectorAll('[data-attribute-editor]')){if(!editor.dataset.listId){editor.dataset.listId=editor.querySelector('datalist')?.id||('attribute-runtime-'+(++editorCounter));for(const row of [...editor.querySelectorAll('[data-attribute-row]')]){const key=row.querySelector('input[name="attribute_keys[]"]')?.value||'';const value=row.querySelector('[data-attribute-value]')?.value||'';row.remove();addRow(editor,key,value);}}editor.querySelector('[data-add-attribute]')?.addEventListener('click',()=>addRow(editor));}
});
</script>
